    if not me.can_drive:
        return (0, 0)
    tx = enemy.x
    ty = enemy.y
    h = radians(me.heading)
    tipx = me.x + 1.5 * cos(h)
    tipy = me.y + 1.5 * sin(h)
    dist_tip = sqrt(tipx*tipx + tipy*tipy)
    dist_me = sqrt(me.x*me.x + me.y*me.y)
    if dist_tip > arena.radius - 0.3 or dist_me > arena.radius - 0.8:
        tx = 0.0
        ty = 0.0
